from tvbo import SimulationExperiment

# Uses standard NeuroML types: pointCellCondBased + ionChannelHH + gateHHrates
# Q10 temperature scaling handled via q10Settings on each gate
# Tissue wrapper changes temperature from 22°C to 16°C at 500ms

exp = SimulationExperiment.from_string("""
label: "NeuroML Ex17: HH Tissue with Q10"
dynamics:
  name: HH_Tissue_Q10
  iri: neuroml:pointCellCondBased
  description: &gt;
    HH cell with Q10 temperature scaling in a tissue that changes
    temperature from 22°C to 16°C at t=500ms.
  parameters:
    C:              { value: 10, unit: pF }
    v0:             { value: -65, unit: mV }
    thresh:         { value: 20, unit: mV }
    pulse_delay:    { value: 0, unit: ms }
    pulse_duration: { value: 1000, unit: ms }
    I_amp:          { value: 0.08, unit: nA }
    tissue_startTemperature: { value: 22, unit: degC }
    tissue_endTemperature:   { value: 16, unit: degC }
    tissue_changeTime:       { value: 500, unit: ms }
  components:
    passive:
      name: passive
      iri: neuroml:ionChannelPassive
      parameters:
        conductance: { value: 10, unit: pS }
        number:      { value: 300 }
        erev:        { value: -54.3, unit: mV }
    na:
      name: na
      iri: neuroml:ionChannelHH
      parameters:
        conductance: { value: 10, unit: pS }
        number:      { value: 120000 }
        erev:        { value: 50, unit: mV }
      components:
        m:
          name: m
          iri: neuroml:gateHHrates
          parameters:
            instances: { value: 3 }
          components:
            q10Settings:
              name: q10Settings
              iri: neuroml:q10ExpTemp
              parameters:
                q10Factor:        { value: 3 }
                experimentalTemp: { value: 32, unit: degC }
            forwardRate:
              name: forwardRate
              iri: neuroml:HHExpLinearRate
              parameters:
                rate:     { value: 1, unit: per_ms }
                midpoint: { value: -40, unit: mV }
