                vHalf:  { value: 0, unit: mV }
                z:      { value: 1.5 }
                gamma:  { value: 0.75 }
                tau:    { value: 3.2, unit: ms }
                tauMin: { value: 0.3, unit: ms }
integration:
  step_size: 0.01
  duration: 300.0
  time_scale: ms
""")
